package webui

// stylesConfig is the configuration editor workbench base, plus the node-config (v36), wide-editor (v40) and hierarchy (v41) refinements.
// Each const holds one contiguous slice of the stylesheet; the global order is
// reassembled in styles_desktop_app.go. Keep every const byte-identical to the
// corresponding line range of the original single-const layout.
const stylesConfig = `.config-workspace{border:1px solid var(--line);border-radius:9px;background:var(--surface);box-shadow:var(--shadow);overflow:hidden}.editor-toolbar{min-height:72px;display:flex;align-items:center;justify-content:space-between;padding:13px 16px;border-bottom:1px solid var(--line)}.editor-toolbar h2{margin-top:2px;font-size:18px}.editor-toolbar>div>span{color:var(--muted);font-size:9px}.editor-toolbar-state{display:flex;align-items:center;gap:9px}.editor-toolbar-state b{font-size:16px}.config-editor-grid{display:grid;grid-template-columns:minmax(0,1fr) 280px}.code-workspace{min-width:0}.code-workspace>header{height:50px;display:flex;align-items:center;justify-content:space-between;padding:0 14px;border-bottom:1px solid var(--line);background:var(--surface-2)}.code-workspace>header b{display:block;font-size:10px}.code-workspace>header small{color:var(--muted);font-size:8px}.code-workspace>textarea{width:100%;min-height:500px;display:block;border:0;border-radius:0;resize:vertical;font-size:11px;line-height:1.65}.code-workspace>footer{display:flex;align-items:center;justify-content:space-between;padding:10px 14px;border-top:1px solid var(--line)}.code-workspace>footer span{color:var(--muted);font-size:9px}.config-inspector{padding:16px;border-left:1px solid var(--line);background:var(--surface-2)}.config-inspector h3{margin-top:2px;font-size:14px}.config-inspector label{display:grid;gap:4px;margin-top:12px;font-size:9px;font-weight:700}.description-input{min-height:90px}.inspector-rules{display:grid;gap:4px;margin-top:18px;padding-top:12px;border-top:1px solid var(--line)}.inspector-rules b{font-size:10px}.inspector-rules small{color:var(--muted);font-size:8px}.inspector-rules small:before{content:"✓";margin-right:4px;color:var(--green)}.delivery-bar{display:grid;grid-template-columns:minmax(230px,.8fr) minmax(500px,1.5fr);align-items:center;gap:18px;padding:14px 16px;border-top:1px solid var(--line);background:var(--surface-2)}.delivery-bar>div{display:flex;align-items:center;gap:10px}.delivery-icon{width:36px;height:36px;display:grid;place-items:center;border-radius:8px;background:var(--accent-soft);color:var(--accent)}.delivery-icon svg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:1.8}.delivery-bar h3{font-size:12px}.delivery-bar small{color:var(--muted);font-size:8px}.delivery-bar form{display:grid;grid-template-columns:1fr 150px auto;align-items:end;gap:7px}.delivery-bar label{display:grid;gap:3px;font-size:9px;font-weight:700}.revision-timeline{border-top:1px solid var(--line)}.revision-timeline>summary{min-height:58px;display:flex;align-items:center;justify-content:space-between;padding:10px 16px;cursor:pointer}.revision-timeline>summary b,.revision-timeline>summary small{display:block}.revision-timeline>summary b{font-size:11px}.revision-timeline>summary small,.revision-timeline>summary>strong{color:var(--muted);font-size:8px}.timeline-body{display:grid;grid-template-columns:210px 1fr;min-height:280px;border-top:1px solid var(--line)}.timeline-body>nav{padding:7px;border-right:1px solid var(--line);background:var(--surface-2)}.timeline-body>nav a{min-height:50px;display:grid;grid-template-columns:8px 1fr;gap:7px;padding:7px;border-radius:6px}.timeline-body>nav a.active{background:var(--surface)}.timeline-body>nav a>i{width:7px;height:7px;margin-top:4px;border:1px solid var(--line-2);border-radius:50%}.timeline-body>nav a.current>i,.timeline-body>nav a.active>i{border-color:var(--accent);background:var(--accent)}.timeline-body>nav b,.timeline-body>nav strong,.timeline-body>nav small{display:block}.timeline-body>nav b{font-size:10px}.timeline-body>nav strong,.timeline-body>nav small{font-size:8px}.timeline-body>nav small{color:var(--muted)}.timeline-preview{padding:12px;background:var(--surface-2)}.timeline-preview>header{display:flex;justify-content:space-between;margin-bottom:7px}.timeline-preview>header b,.timeline-preview>header small{display:block}.timeline-preview>header small{color:var(--muted);font-size:8px}.timeline-preview textarea{width:100%;min-height:210px;font-size:10px}.timeline-placeholder{display:grid;place-items:center;color:var(--muted);font-size:10px}.config-danger{display:flex;justify-content:space-between;padding:10px 16px;border-top:1px solid var(--line);background:var(--red-soft)}.config-danger b,.config-danger small{display:block}.config-danger b{color:var(--red);font-size:10px}.config-danger small{color:var(--muted);font-size:8px}.config-danger button{border:0;background:transparent;color:var(--red);font-size:9px}
`

const stylesNodeConfig = `/* Node configuration v36: one compact selector bar and one editing surface. */
.page-agent-config .context-back,.page-agent-config .context-steps{display:none}.config-command-bar,.config-command-bar.loaded{display:block;margin-bottom:12px;padding:0;border:1px solid var(--line);border-radius:14px;background:var(--surface);box-shadow:var(--shadow);overflow:hidden}.config-command-bar.loaded{border-color:color-mix(in srgb,var(--green) 24%,var(--line))}.config-command-head{display:flex;align-items:center;justify-content:space-between;gap:18px;min-height:72px;padding:12px 16px;border-bottom:1px solid var(--line);background:linear-gradient(135deg,var(--surface),color-mix(in srgb,var(--green-soft) 24%,var(--surface)))}.config-command-title{min-width:0;display:flex;align-items:center;gap:11px}.config-command-title h2{margin-top:2px;font-size:18px;letter-spacing:-.02em}.config-command-title small{display:block;overflow:hidden;max-width:720px;margin-top:2px;color:var(--muted);font-size:9px;text-overflow:ellipsis;white-space:nowrap}.config-command-state{display:flex;align-items:center;justify-content:flex-end;gap:10px;flex:0 0 auto}.config-command-state>a{color:var(--accent);font-size:9px;font-weight:700}.config-command-state .recipe-version{min-width:38px}.config-command-selectors{display:grid;grid-template-columns:minmax(230px,.58fr) minmax(0,1.42fr);background:var(--line)}.config-command-selectors>.config-selector{min-width:0;display:grid;grid-template-columns:auto minmax(0,1fr);align-items:center;margin:0;border:0;border-radius:0;background:var(--surface);box-shadow:none}.config-command-selectors>.config-selector:only-child{grid-column:1/-1}.config-command-selectors>.config-selector+ .config-selector{margin-left:1px}.config-selector>header,.config-selector.protocol-browser>header{min-width:88px;min-height:58px;display:flex;align-items:flex-start;flex-direction:column;justify-content:center;gap:3px;padding:8px 12px;border:0}.config-selector>header>span{display:flex;align-items:center;gap:6px}.config-selector>header b{margin:0;font-size:10px}.config-selector>header small{font-size:8px}.config-selector>header .button{min-height:28px;padding:4px 7px;font-size:8px}.config-selector>nav,.config-selector.protocol-browser>nav{min-width:0;display:flex;gap:6px;padding:7px 9px;overflow-x:auto;scrollbar-width:thin}.config-selector.inbound-browser>nav>a{min-width:138px;display:block;padding:6px 8px;border:1px solid var(--line);border-radius:8px}.config-selector.inbound-browser>nav>a.active{border-color:var(--accent);background:var(--accent-soft)}.config-selector.protocol-browser>nav>a{min-width:max-content;display:flex;grid-template-columns:none;align-items:center;gap:6px;padding:6px 9px;border:1px solid transparent;border-radius:8px}.config-selector.protocol-browser>nav>a.active{border-color:var(--accent);background:var(--accent-soft);box-shadow:none}.config-selector.protocol-browser>nav a>b{width:auto;min-width:28px;height:26px;padding:0 5px}.config-selector.protocol-browser strong{font-size:9px}.page-agent-config .recipe-workspace{margin-top:0}.page-agent-config .config-mutation{display:grid;grid-template-columns:minmax(0,1fr) minmax(220px,310px);align-items:center;gap:14px;margin:14px 16px 10px;padding:9px 11px}.page-agent-config .config-mutation>span b{margin:0;font-size:11px}.page-agent-config .config-mutation>span small{margin-top:1px}.page-agent-config .config-mutation>label{grid-template-columns:auto minmax(180px,1fr);align-items:center;gap:8px}.page-agent-config .config-mutation select{height:38px;min-width:0}.page-agent-config .builder-layout{grid-template-columns:minmax(0,1fr)}.page-agent-config .builder-index{display:flex;gap:5px;padding:7px 12px;border-right:0;border-bottom:1px solid var(--line);background:color-mix(in srgb,var(--accent-soft) 32%,var(--surface-2));overflow-x:auto}.page-agent-config .builder-index a{min-width:max-content;align-items:center;gap:6px;padding:6px 8px}.page-agent-config .builder-index b{width:24px;height:24px}.page-agent-config .builder-index small{display:none}
@media(max-width:820px){.config-command-head{align-items:flex-start;flex-direction:column;gap:9px;padding:11px 12px}.config-command-title{align-items:flex-start}.config-command-title small{max-width:270px;white-space:normal}.config-command-state{width:100%;justify-content:flex-start;flex-wrap:wrap}.config-command-selectors{grid-template-columns:1fr}.config-command-selectors>.config-selector{grid-column:1;grid-template-columns:76px minmax(0,1fr)}.config-command-selectors>.config-selector+ .config-selector{margin-top:1px;margin-left:0}.config-selector>header,.config-selector.protocol-browser>header{min-width:0;padding:7px 9px}.config-selector.inbound-browser>nav>a{min-width:150px}.page-agent-config .config-mutation{grid-template-columns:1fr;margin:10px;padding:10px}.page-agent-config .config-mutation>label{grid-template-columns:1fr}.page-agent-config .builder-index{padding-inline:9px}.page-agent-config .builder-index a{min-width:max-content}}

`

const stylesWideConfig = `/* Wide configuration editor v40: use the available width instead of stacking sparse sections. */
@media(min-width:1101px){.page-agent-config .config-mutation{min-height:50px;margin:10px 12px 0;padding:7px 10px;border-color:var(--line);background:var(--surface)}.page-agent-config .builder-index{display:none}.page-agent-config .builder-sections{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));align-items:start;gap:12px;padding:12px;background:color-mix(in srgb,var(--surface-2) 82%,var(--canvas))}.page-agent-config .builder-section{min-width:0;margin:0;padding:16px;border:1px solid var(--line);border-radius:12px;background:var(--surface);box-shadow:0 8px 24px -24px rgba(79,70,229,.5)}.page-agent-config .builder-section.security-section{grid-column:1/-1}.page-agent-config .plan-fields.two:has(>label:only-of-type){grid-template-columns:minmax(0,1fr)}.page-agent-config .builder-actions{padding-inline:16px}}

`

const stylesHierarchy = `/* Hierarchical configuration workbench v41: reveal one decision level at a time. */
.config-hierarchy-menu{background:var(--surface)}.config-hierarchy-menu>summary{min-height:48px;display:flex;align-items:center;justify-content:space-between;gap:16px;padding:8px 16px;cursor:pointer}.config-hierarchy-menu>summary:hover{background:var(--surface-2)}.config-hierarchy-menu>summary b,.config-hierarchy-menu>summary small{display:block}.config-hierarchy-menu>summary b{font-size:10px}.config-hierarchy-menu>summary small{margin-top:1px;color:var(--muted);font-size:8px}.config-hierarchy-menu>summary i{display:flex;align-items:center;gap:6px;color:var(--accent);font-size:9px;font-style:normal;font-weight:700}.config-hierarchy-menu>summary i:after{content:"+";width:20px;height:20px;display:grid;place-items:center;border:1px solid var(--line);border-radius:6px;background:var(--surface)}.config-hierarchy-menu[open]>summary{border-bottom:1px solid var(--line)}.config-hierarchy-menu[open]>summary i{font-size:0}.config-hierarchy-menu[open]>summary i:before{content:"收起";font-size:9px}.config-hierarchy-menu[open]>summary i:after{content:"−"}.page-agent-config .builder-index>header{padding:6px 8px 11px;border-bottom:1px solid var(--line)}.page-agent-config .builder-index>header b,.page-agent-config .builder-index>header small{width:auto;height:auto;display:block;border-radius:0;background:transparent;color:inherit}.page-agent-config .builder-index>header b{font-size:10px}.page-agent-config .builder-index>header small{margin-top:2px;color:var(--muted);font-size:8px}.page-agent-config .builder-index>a.active{background:var(--accent-soft);color:var(--ink);box-shadow:inset 3px 0 0 var(--accent)}.page-agent-config .builder-index>a.active>b{background:var(--accent);color:var(--on-accent)}
@media(min-width:1101px){.page-agent-config .builder-layout{display:grid;grid-template-columns:200px minmax(0,1fr)}.page-agent-config .builder-index{display:block;padding:10px;border-right:1px solid var(--line);border-bottom:0;background:color-mix(in srgb,var(--surface-2) 88%,var(--canvas));overflow:visible}.page-agent-config .builder-index>a{min-width:0;align-items:center;margin-top:4px;padding:9px}.page-agent-config .builder-index small{display:block}.page-agent-config .builder-sections{display:block;padding:14px;background:color-mix(in srgb,var(--surface-2) 82%,var(--canvas))}.page-agent-config .builder-section,.page-agent-config .builder-section.security-section{max-width:1080px;margin:0 auto;padding:18px;border:1px solid var(--line);border-radius:12px;background:var(--surface);box-shadow:0 8px 24px -24px rgba(79,70,229,.5)}.page-agent-config .plan-fields.two:has(>label:only-of-type){grid-template-columns:minmax(0,1fr)}}
@media(max-width:820px){.config-hierarchy-menu>summary{align-items:flex-start;padding:9px 12px}.config-hierarchy-menu>summary span{min-width:0}.config-hierarchy-menu>summary small{overflow:hidden;max-width:240px;text-overflow:ellipsis;white-space:nowrap}.page-agent-config .builder-layout{display:block}.page-agent-config .builder-index{display:flex;padding:7px 9px}.page-agent-config .builder-index>header{display:none}.page-agent-config .builder-index>a{min-width:max-content}.page-agent-config .builder-sections{display:block;padding:10px;background:var(--surface-2)}.page-agent-config .builder-section,.page-agent-config .builder-section.security-section{margin:0;padding:16px 14px;border:1px solid var(--line);border-radius:11px;background:var(--surface)}}

`

const stylesTemplates = `/* Config templates: reusable per-node configuration bodies. */

.template-workspace{margin-top:18px;padding:16px;border:1px solid var(--line);border-radius:12px;background:var(--surface)}.template-head{display:flex;align-items:baseline;justify-content:space-between;gap:12px}.template-head h3{font-size:16px}.template-head span{color:var(--muted);font-size:9px}.template-create{margin-top:12px;border:1px solid var(--line);border-radius:9px;overflow:hidden}.template-create>summary{min-height:38px;display:flex;align-items:center;padding:8px 12px;font-size:10px;font-weight:800;cursor:pointer}.template-create>form{display:grid;grid-template-columns:1fr 1fr;gap:10px;padding:12px;background:var(--surface-2)}.template-create label{display:grid;gap:4px;font-size:9px;font-weight:700}.template-content-field{grid-column:1/-1}.template-create textarea{min-height:140px;font-family:var(--mono);font-size:10px}.template-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:10px;margin-top:12px}.template-card{border:1px solid var(--line);border-radius:10px;background:var(--surface-2);overflow:hidden}.template-card>header{display:flex;align-items:center;gap:8px;padding:9px 11px;border-bottom:1px solid var(--line)}.template-card h4{min-width:0;overflow:hidden;font-size:11px;text-overflow:ellipsis;white-space:nowrap}.template-card>header small{margin-left:auto;color:var(--muted);font-size:8px}.template-card pre{max-height:170px;margin:0;padding:10px 11px;overflow:auto;color:var(--ink-2);font-family:var(--mono);font-size:9px;line-height:1.6;white-space:pre-wrap;word-break:break-all}.template-card>footer{display:flex;justify-content:space-between;gap:8px;padding:8px 11px;border-top:1px solid var(--line)}.template-card>footer form{display:flex;align-items:center;gap:6px;margin:0}.template-card>footer label{display:flex;align-items:center;gap:4px;font-size:8px;font-weight:700}.template-card>footer select{min-height:28px;font-size:9px}.template-empty{margin:14px 0 4px;color:var(--muted);font-size:10px}
`
